<script setup lang="ts">
import { toRef } from 'vue';
import { Copy, Globe2, KeyRound, Pause, Pencil, Play, Plus, RefreshCw, Search, ShieldCheck, Trash2 } from 'lucide-vue-next';
import { useConsole } from '../composables/useConsole';
import { useTable } from '../composables/useTable';
import { countText, dateText } from '../utils/format';
const workspace = useConsole();
const table = useTable(toRef(workspace, 'filteredClients'));
function percent(used = 0, limit?: number | null) { return limit ? Math.min(100, Math.round(used / limit * 100)) : null; }
</script>
<template>
  <section class="endpoint-card"><span class="endpoint-icon"><Globe2 :size="23" /></span><div><span class="eyebrow">统一内网地址 · OpenAI / Anthropic</span><code>{{ workspace.baseUrl || '尚未配置内网地址' }}</code></div><button class="button secondary" :disabled="!workspace.baseUrl" @click="workspace.copyText(workspace.baseUrl)"><Copy :size="15" />复制地址</button></section><div class="info-strip"><ShieldCheck :size="18" /><span>原始密钥仅在创建或轮换时显示一次。数据库仅保存加盐哈希，不提供密钥找回。token 限额在请求开始前检查，单次请求可能略微超出。</span></div>
  <section class="panel table-panel"><div class="table-toolbar"><div class="search-input"><Search :size="17" /><input v-model="workspace.search" aria-label="搜索出口 key" placeholder="搜索出口 key 名称、备注…" /></div><select v-model="workspace.groupFilter" aria-label="筛选出口 key 分组"><option value="">全部分组</option><option v-for="group in workspace.groups" :key="group.id" :value="group.id">{{ group.name }}</option></select><span class="muted">{{ workspace.filteredClients.length }} / {{ workspace.clients.length }} 个出口 key</span></div><div class="table-scroll"><table><thead><tr><th scope="col"><button class="text-button" @click="table.sortBy('name')">出口 key</button></th><th scope="col">密钥 / 状态</th><th scope="col">模型权限</th><th scope="col"><button class="text-button" @click="table.sortBy('requests')">使用情况</button></th><th scope="col">限额</th><th scope="col">过期时间</th><th class="align-right" scope="col">操作</th></tr></thead><tbody><tr v-for="row in table.rows" :key="row.id"><td><div class="entity-name"><span class="entity-avatar amber-bg"><KeyRound :size="17" /></span><div><strong>{{ row.name }}</strong><small>分组 · {{ workspace.groupName(row.group_id) }}</small><small>{{ row.notes || '独立出口访问凭据' }}</small></div></div></td><td><code>{{ row.key_prefix }}</code> <button class="text-button" @click="workspace.copyText(row.key_prefix)">复制前缀</button><small class="cell-sub"><span :class="['pill', !row.enabled ? 'disabled' : row.expires_at && row.expires_at < Date.now() ? 'cooling' : 'ready']">{{ !row.enabled ? '已停用' : row.expires_at && row.expires_at < Date.now() ? '已过期' : '有效' }}</span></small></td><td><span class="pill neutral">{{ row.whitelist.length ? row.whitelist.length + ' 条规则' : '不限制' }}</span></td><td><strong>{{ countText(row.requests) }}</strong><small class="cell-sub">成功 {{ row.successes }} · 失败 {{ row.errors }}</small><small class="cell-sub">最近 {{ dateText(row.last_used_at) }}</small></td><td><small class="cell-sub">当日 {{ row.daily_token_limit ? `${countText(row.day_tokens)} / ${countText(row.daily_token_limit)}（${percent(row.day_tokens, row.daily_token_limit)}%）` : '不限制' }}</small><small class="cell-sub">当月 {{ row.monthly_token_limit ? `${countText(row.month_tokens)} / ${countText(row.monthly_token_limit)}（${percent(row.month_tokens, row.monthly_token_limit)}%）` : '不限制' }}</small><small v-if="row.rpm_limit || row.max_concurrency" class="cell-sub">{{ row.rpm_limit ? row.rpm_limit + ' 次/分钟' : '' }} {{ row.max_concurrency ? '并发 ' + row.max_concurrency : '' }}</small></td><td class="small">{{ row.expires_at ? dateText(row.expires_at) : '永不过期' }}</td><td><div class="row-actions"><button class="icon-button" :aria-label="`编辑 ${row.name}`" title="编辑出口 key" @click="workspace.editor = { kind: 'clients', item: row }"><Pencil :size="16" /></button><button class="icon-button" :aria-label="`轮换 ${row.name}`" title="轮换密钥" @click="workspace.grace = 0; workspace.confirmation = { kind: 'clients', id: row.id, name: row.name, action: 'rotate' }"><RefreshCw :size="16" /></button><button class="icon-button" :disabled="workspace.busy === row.id" :aria-label="`${row.enabled ? '停用' : '启用'} ${row.name}`" :title="row.enabled ? '停用' : '启用'" @click="workspace.toggle('clients', row)"><Pause v-if="row.enabled" :size="16" /><Play v-else :size="16" /></button><button class="icon-button danger" :aria-label="`撤销 ${row.name}`" title="撤销出口 key" @click="workspace.confirmation = { kind: 'clients', id: row.id, name: row.name, action: 'delete' }"><Trash2 :size="16" /></button></div></td></tr></tbody></table></div><footer v-if="table.pages > 1" class="table-footer"><span>第 {{ table.page }} / {{ table.pages }} 页</span><span><button class="text-button" :disabled="table.page === 1" @click="table.page--">上一页</button><button class="text-button" :disabled="table.page === table.pages" @click="table.page++">下一页</button></span></footer><div v-if="!workspace.filteredClients.length" class="empty-state"><KeyRound :size="32" /><h3>{{ workspace.search ? '没有匹配的出口 key' : workspace.groupFilter ? '此分组暂无出口 key' : '为第一个客户端创建出口 key' }}</h3><p>每个密钥独立授权、统计和轮换。</p><button v-if="!workspace.search" class="button secondary" @click="workspace.editor = { kind: 'clients' }"><Plus :size="16" />创建出口 key</button></div></section>
</template>
